137	    <script>
138	        const GROUPS = __GROUPS_JSON__;
139	        const STATS = __STATS_JSON__;
140	
141	        // 計算「距今幾個月」
142	        function monthsSince(visit_date) {
143	            const visit = new Date(visit_date);
144	            const now = new Date();
145	            const yearsDiff = now.getFullYear() - visit.getFullYear();
146	            const monthsDiff = now.getMonth() - visit.getMonth();
147	            let totalMonths = yearsDiff * 12 + monthsDiff;
148	            if (now.getDate() < visit.getDate()) totalMonths -= 1;
149	            return Math.max(0, totalMonths);
150	        }
151	
152	        // 預先算好每個組合的「距今月數」，存進 record
153	        const ENRICHED = GROUPS.map(g => ({
154	            ...g,
155	            months_ago: monthsSince(g.visit_date)
156	        }));
157	
158	        // 過�：months_ago >= N
159	        function filterByWindow(months) {
160	            if (months === 'all') return ENRICHED.slice();
161	            const n = parseInt(months, 10);
162	            return ENRICHED.filter(r => r.months_ago >= n);
163	        }
164	
165	        // 排序：距今月數由大到小（最久沒邀約在最上面）
166	        function renderList(filtered) {
167	            const sorted = filtered.slice().sort((a, b) => b.months_ago - a.months_ago);
168	            const tbody = document.getElementById('rankTableBody');
169	            if (sorted.length === 0) {
170	                tbody.innerHTML = '<tr><td colspan="5" class="empty">這個門�下沒有會員（每位會員最近都有邀約來賓）</td></tr>';
171	                return;
172	            }
173	            const html = sorted.map((r, i) => {
174	                const isWarn = r.months_ago >= 12;
175	                const cls = isWarn ? 'warn' : '';
176	                return `<tr class="${cls}">
177	                    <td>${i + 1}</td>
178	                    <td>${r.inviter}</td>
179	                    <td>${r.chapter}</td>
180	                    <td>${r.visit_date}</td>
181	                    <td class="months">${r.months_ago} 個月</td>
182	                </tr>`;
183	            }).join('');
184	            tbody.innerHTML = html;
185	        }
186	
187	        function renderStats(filtered) {
188	            const el = document.getElementById('statsRow');
189	            el.innerHTML = `
190	                <div class="stat-card"><div class="num">${filtered.length}</div><div class="lbl">超過門檻人數</div></div>
191	                <div class="stat-card"><div class="num">${STATS.total_groups}</div><div class="lbl">(邀請人, 分會) 組合</div></div>
192	                <div class="stat-card"><div class="num">${STATS.unique_inviters}</div><div class="lbl">獨立邀請人數</div></div>
193	                <div class="stat-card"><div class="num">${STATS.chapters.length}</div><div class="lbl">涵蓋分會數</div></div>
194	            `;
195	        }
196	
197	        function renderSub(filtered, months) {
198	            const sub = document.getElementById('rankSub');
199	            const label = months === 'all' ? '全部 8 年+ 歷史紀錄' : `最近一次邀約已超過 ${months} 個月`;
200	            sub.innerHTML = `${label}｜共 ${filtered.length} 個 (邀請人, 分會) 組合`;
201	        }
202	
203	        let currentMonths = 6;
204	        function apply(months) {
205	            currentMonths = months;
206	            const filtered = filterByWindow(months);
207	            renderStats(filtered);
208	            renderSub(filtered, months);
209	            renderList(filtered);
210	            // 更新 tab 樣式
211	            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
212	            if (typeof months === 'string') {
213	                document.querySelector(`.tab-btn[data-months="${months}"]`)?.classList.add('active');
214	            }
215	        }
216	
217	        // tab 按鈕
218	        document.querySelectorAll('#tabs .tab-btn').forEach(btn => {
219	            btn.addEventListener('click', () => {
220	                const m = btn.dataset.months === 'all' ? 'all' : parseInt(btn.dataset.months, 10);
221	                apply(m);
222	            });
223	        });
224	
225	        // 自訂輸入框
226	        document.getElementById('customMonthsBtn').addEventListener('click', () => {
227	            const v = parseInt(document.getElementById('customMonths').value, 10);
228	            if (!v || v < 1) {
229	                alert('請輸入正整數月數');
230	                return;
231	            }
232	            apply(v);
233	        });
234	
235	        // 初始 render
236	        apply(6);
237	    </script>
238	</body>
239	</html>
