143	        function monthsSince(visit_date) {
144	            const visit = new Date(visit_date);
145	            const now = new Date();
146	            const yearsDiff = now.getFullYear() - visit.getFullYear();
147	            const monthsDiff = now.getMonth() - visit.getMonth();
148	            let totalMonths = yearsDiff * 12 + monthsDiff;
149	            if (now.getDate() < visit.getDate()) totalMonths -= 1;
150	            return Math.max(0, totalMonths);
151	        }
