176	                <div class="stat-card"><div class="num">${totalGuests}</div><div class="lbl">邀約來賓人次</div></div>
177	                <div class="stat-card"><div class="num">${invited.length}</div><div class="lbl">有邀約的會員數</div></div>
178	                <div class="stat-card"><div class="num">${members.length}</div><div class="lbl">分會會員總數</div></div>
179	            `;
180	        }
181	
182	        function renderRanking(members) {
183	            const ranked = members.filter(m => m.count > 0);
184	            const top10 = ranked.slice(0, 10);
185	
186	            const sub = document.getElementById('rankSub');
187	            const podiumArea = document.getElementById('podiumArea');
188	            const listArea = document.getElementById('rankListArea');
189	
190	            sub.innerHTML = `${currentChapter}分會・近${currentMonths}個月`;
191	
192	            if (top10.length === 0) {
193	                podiumArea.innerHTML = '<div class="empty-note">這個時間範圍內還沒有邀約來賓紀錄</div>';
194	                listArea.innerHTML = '';
195	                return;
196	            }
197	
198	            const congrats = document.createElement('div');
199	            const top3 = top10.slice(0, 3);
200	            podiumArea.innerHTML = '<div class="congrats">★ 恭喜以下夥伴，熱心邀約來賓、壯大分會 ★</div><div class="podium">' + top3.map((p, i) => `
201	                <div class="podium-card rank-${i + 1}">
202	                    <div class="medal">${MEDALS[i]}</div>
203	                    <div class="podium-name">${p.name}</div>
204	                    <div class="podium-count">${p.count}</div>
205	                    <div class="podium-count-lbl">位來賓</div>
206	                </div>
207	            `).join('') + '</div>';
208	
209	            const rest = top10.slice(3);
210	            if (rest.length === 0) {
211	                listArea.innerHTML = '';
212	            } else {
213	                listArea.innerHTML = '<div class="rank-list">' + rest.map((p, i) => `
214	                    <div class="rank-row">
215	                        <div class="rank-badge">${i + 4}</div>
216	                        <div class="rname">${p.name}</div>
217	                        <div class="rcount">${p.count} 位</div>
218	                    </div>
219	                `).join('') + '</div>';
220	            }
221	        }
222	
223	        function renderAll() {
224	            const members = currentMembers();
225	            renderStats(members);
226	            renderRanking(members);
227	        }
228	
229	        // 初始化：預設抓6個月門檻（跟培訓總覽index.html預設一致），沒有剛好6個月的快照就退而求其次選最接近的
230	        function defaultMonths(months) {
231	            if (months.includes(6)) return 6;
232	            return months.reduce((best, m) => Math.abs(m - 6) < Math.abs(best - 6) ? m : best, months[0]);
233	        }
234	        currentMonths = defaultMonths(CHAPTERS[currentChapter].months_available);
235	        renderChapterTabs();
236	        renderMonthTabs();
237	        renderAll();
238	    </script>
239	</body>
240	</html>
