7	<style>
8	/* 色系/字型取自 chapters.bymyway.com/sincere（BNI官方Brand Standards Manual指定色） */
9	:root {
10	    --red: #CF2030; --red-dark: #9B1F27; --ink: #000000; --paper: #FAF7F2;
