212	    <script>
213	        const RECORDS = __RECORDS_JSON__;
214	        const ROSTER = __ROSTER_JSON__;
215	        const MEDALS = ['🥇', '🥈', '🥉'];
216	
217	        // 每個人最後一次受訓日期(不受時間窗影響，看全部歷史)，反向查詢名單要顯示這個當參考
218	        const LAST_TRAINED = {};
219	        RECORDS.forEach(r => {
220	            if (!LAST_TRAINED[r.name] || r.event_date > LAST_TRAINED[r.name]) {
221	                LAST_TRAINED[r.name] = r.event_date;
222	            }
223	        });
224	
225	        function monthsAgo(n) {
226	            const d = new Date();
227	            d.setMonth(d.getMonth() - n);
228	            return d;
229	        }
230	
231	        function fmtDate(d) {
232	            return d.toISOString().slice(0, 10);
233	        }
234	
235	        function filterByWindow(months) {
236	            if (months === 'all') return RECORDS.slice();
237	            const cutoff = fmtDate(monthsAgo(parseInt(months, 10)));
238	            return RECORDS.filter(r => r.event_date >= cutoff);
239	        }
240	
241	        function renderStats(filtered) {
242	            const people = new Set(filtered.map(r => r.name));
243	            const chapters = new Set(filtered.map(r => r.chapter).filter(Boolean));
244	            const el = document.getElementById('statsRow');
245	            el.innerHTML = `
246	                <div class="stat-card"><div class="num">${filtered.length}</div><div class="lbl">培訓人次</div></div>
247	                <div class="stat-card"><div class="num">${people.size}</div><div class="lbl">參與會員數</div></div>
248	                <div class="stat-card"><div class="num">${chapters.size}</div><div class="lbl">涵蓋分會數</div></div>
249	            `;
250	        }
251	
252	        function renderRanking(filtered) {
253	            const counts = {};
254	            filtered.forEach(r => {
255	                if (!counts[r.name]) counts[r.name] = { name: r.name, chapter: r.chapter, count: 0 };
256	                counts[r.name].count++;
257	            });
258	            const ranked = Object.values(counts).sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));
259	            const top10 = ranked.slice(0, 10);
260	
261	            const sub = document.getElementById('rankSub');
262	            const podiumArea = document.getElementById('podiumArea');
263	            const listArea = document.getElementById('rankListArea');
264	
265	            if (top10.length === 0) {
266	                sub.textContent = '';
267	                podiumArea.innerHTML = '<div class="empty-note">這個時間範圍內還沒有培訓紀錄</div>';
268	                listArea.innerHTML = '';
269	                return;
270	            }
271	
272	            sub.innerHTML = '<span class="congrats">★ 恭喜以下夥伴，持續投資自己、全力以赴成長 ★</span>';
273	
274	            const top3 = top10.slice(0, 3);
275	            podiumArea.innerHTML = '<div class="podium">' + top3.map((p, i) => `
276	                <div class="podium-card rank-${i + 1}">
277	                    <div class="medal">${MEDALS[i]}</div>
278	                    <div class="podium-name">${p.name}</div>
279	                    <div class="podium-chapter">${p.chapter || '-'}</div>
280	                    <div class="podium-count">${p.count}</div>
281	                    <div class="podium-count-lbl">次培訓</div>
282	                </div>
283	            `).join('') + '</div>';
284	
285	            const rest = top10.slice(3);
286	            if (rest.length === 0) {
287	                listArea.innerHTML = '';
288	            } else {
289	                listArea.innerHTML = '<div class="rank-list">' + rest.map((p, i) => `
290	                    <div class="rank-row">
291	                        <div class="rank-badge">${i + 4}</div>
292	                        <div class="rname">${p.name}</div>
293	                        <div class="rchapter">${p.chapter || '-'}</div>
294	                        <div class="rcount">${p.count} 次</div>
295	                    </div>
296	                `).join('') + '</div>';
297	            }
298	        }
299	
300	        function renderChapterRank(filtered) {
301	            const stats = {};
302	            filtered.forEach(r => {
303	                if (!r.chapter) return; // 分會未知的紀錄不參與分會排名比較
304	                if (!stats[r.chapter]) stats[r.chapter] = { chapter: r.chapter, count: 0, people: new Set() };
305	                stats[r.chapter].count++;
306	                stats[r.chapter].people.add(r.name);
307	            });
308	            const ranked = Object.values(stats).sort((a, b) => b.count - a.count);
309	            const maxCount = ranked.length ? ranked[0].count : 1;
310	            const el = document.getElementById('chapterRankArea');
311	
312	            if (ranked.length === 0) {
313	                el.innerHTML = '<div class="empty-note">這個時間範圍內還沒有培訓紀錄</div>';
314	                return;
315	            }
316	
317	            el.innerHTML = ranked.map((c, i) => {
318	                const avg = (c.count / c.people.size).toFixed(1);
319	                const pct = Math.max(6, Math.round((c.count / maxCount) * 100));
320	                return `
321	                <div class="chapter-row">
322	                    <div class="chapter-row-head">
323	                        <div class="cname"><span class="badge">No.${i + 1}</span>${c.chapter}</div>
324	                        <div class="cstat">${c.count} 人次｜${c.people.size} 人參與｜平均 ${avg} 次/人</div>
325	                    </div>
326	                    <div class="chapter-bar-bg"><div class="chapter-bar-fill" style="width:${pct}%"></div></div>
327	                </div>`;
328	            }).join('');
329	        }
330	
331	        function renderAbsentees(filtered, months) {
332	            const attendedNames = new Set(filtered.map(r => r.name));
333	            const absentees = ROSTER.filter(p => !attendedNames.has(p.name));
334	            const sub = document.getElementById('absentSub');
335	            const area = document.getElementById('absentArea');
336	            const windowLabel = months === 'all' ? '全部區間' : `近${months}個月`;
337	
338	            if (absentees.length === 0) {
339	                sub.textContent = `${windowLabel}內，全體 ${ROSTER.length} 位會員都至少上過一次課`;
340	                area.innerHTML = '<div class="all-clear">🎉 全員達標，沒有人落後！</div>';
341	                return;
342	            }
343	
344	            sub.textContent = `${windowLabel}內，共 ${absentees.length} / ${ROSTER.length} 位會員沒有任何培訓紀錄`;
345	            area.innerHTML = '<div class="absent-list">' + absentees.map(p => {
346	                const last = LAST_TRAINED[p.name];
347	                const lastHtml = last
348	                    ? `<span class="alast">最後受訓 ${last}</span>`
349	                    : `<span class="alast never">從未有受訓紀錄</span>`;
350	                return `
351	                <div class="absent-row">
352	                    <span class="aicon">⚠️</span>
353	                    <span class="aname">${p.name}</span>
354	                    <span class="achapter">${p.chapter || '-'}</span>
355	                    ${lastHtml}
356	                </div>`;
357	            }).join('') + '</div>';
358	        }
359	
360	        function renderDetail(filtered, query) {
361	            const q = (query || '').trim();
362	            const rows = filtered
363	                .filter(r => !q || r.name.includes(q))
364	                .sort((a, b) => b.event_date.localeCompare(a.event_date));
365	            const body = document.getElementById('detailBody');
366	            if (rows.length === 0) {
367	                body.innerHTML = '<tr><td colspan="4" style="text-align:center;color:#64748b;padding:24px;">沒有符合的紀錄</td></tr>';
368	                return;
369	            }
370	            body.innerHTML = rows.map(r => `
371	                <tr>
372	                    <td class="td-date">${r.event_date}</td>
373	                    <td class="td-name">${r.name}</td>
374	                    <td class="td-chapter">${r.chapter || '-'}</td>
375	                    <td class="td-type">${r.event_type}</td>
376	                </tr>
377	            `).join('');
378	        }
379	
380	        let currentFiltered = [];
381	
382	        function renderAll(months) {
383	            currentFiltered = filterByWindow(months);
384	            renderStats(currentFiltered);
385	            renderRanking(currentFiltered);
386	            renderChapterRank(currentFiltered);
387	            renderAbsentees(currentFiltered, months);
388	            renderDetail(currentFiltered, document.getElementById('searchBox').value);
389	        }
390	
391	        function clearActiveTabs() {
392	            document.querySelectorAll('#tabs .tab-btn').forEach(b => b.classList.remove('active'));
393	            document.getElementById('customMonthsResult').textContent = '';
394	        }
395	
396	        document.querySelectorAll('#tabs .tab-btn').forEach(btn => {
397	            btn.addEventListener('click', () => {
398	                clearActiveTabs();
399	                btn.classList.add('active');
400	                renderAll(btn.dataset.months);
401	            });
402	        });
403	
404	        function runCustomMonths() {
405	            const val = parseInt(document.getElementById('customMonths').value, 10);
406	            if (!val || val < 1) return;
407	            clearActiveTabs();
408	            document.getElementById('customMonthsResult').textContent = `目前顯示：近 ${val} 個月`;
409	            renderAll(String(val));
410	        }
411	        document.getElementById('customMonthsBtn').addEventListener('click', runCustomMonths);
412	        document.getElementById('customMonths').addEventListener('keydown', (e) => {
413	            if (e.key === 'Enter') runCustomMonths();
414	        });
415	
416	        document.getElementById('searchBox').addEventListener('input', (e) => {
417	            renderDetail(currentFiltered, e.target.value);
418	        });
419	
420	        renderAll('6');
421	    </script>
422	</body>
423	</html>
